import re
import datetime
import logging
from moler.device import DeviceFactory
from moler.util.moler_test import MolerTest
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.ue.connections.device_aliases import ue_pc as ue_pc_name


def reboot_uepc_if_needed_and_wait_till_is_up(ue_id=0, max_uptime_days=7):
    """
    Reboot PC when uptime is greater than max_uptime_days.
    :param ue_id:           UE id - related to Test Line configuration - tl.ues.
    :param max_uptime_days: number of uptime days.
    :return: None
    """
    display_tasklist(ue_id=ue_id)
    uptime = get_ue_pc_uptime(ue_id=ue_id)
    logging.info("Current uptime {}".format(uptime))
    if uptime > datetime.timedelta(days=max_uptime_days):
        logging.info("Reboot needed")
        reboot_pc(ue_id=ue_id)
        MolerTest.sleep(seconds=60)
        wait_for_pc_up(ue_id=ue_id)
        DeviceFactory.get_device(name=ue_pc_name.format(ue_id))


def reboot_pc(ue_id=0):
    """
    Reboot PC.
    :param ue_id:   UE id - related to Test Line configuration - tl.ues.
    :return: None
    """
    _send_ue_pc_cmd(ue_id=ue_id, cmd=r'shutdown /r /t 0')


def wait_for_pc_up(ue_id=0, timeout=3 * 60):
    """
    Wait for PC is up
    :param ue_id:   UE id - related to Test Line configuration - tl.ues.
    :param timeout: timeout for waiting for UE PC
    :return: None
    """

    ue_pc = DeviceFactory.get_device(name=ue_pc_name.format(ue_id), establish_connection=False)
    ip_address = ue_pc._configurations['CONNECTION_HOPS']['UNIX_LOCAL']['UNIX_REMOTE']['command_params']['host']

    local_device = DeviceFactory.get_device(name='UnixLocal')
    ping_event = local_device.get_event(event_name='ping_response', event_params={"till_occurs_times": 1})
    ping_event.start()
    cmd_ping = local_device.get_cmd(cmd_name="ping", cmd_params={"destination": ip_address, "options": "-O"})
    cmd_ping.start(timeout=timeout)
    ping_event.await_done(timeout=timeout)
    cmd_ping.cancel()


def get_ue_pc_uptime(ue_id=0):
    """
    Get UE PC uptime
    :param ue_id:   UE id - related to Test Line configuration - tl.ues.
    :return: uptime - as datetime object
    """
    boot_time = get_system_boot_date(ue_id=ue_id)
    current_time = datetime.datetime.now()
    uptime = current_time - boot_time
    return uptime


def get_system_boot_date(ue_id=0):
    """
    Get UE PC system boot date
    :param ue_id:   UE id - related to Test Line configuration - tl.ues.
    :return: boot date as datetime object
    """

    # 20211214152846.500000+060
    _re_system_boot_time = re.compile(r'\d+\.\d+(\+|-\d+)')
    results = _run_and_get_command_output(cmd='wmic path Win32_OperatingSystem get LastBootUpTime', ue_id=ue_id)

    for line in results:
        match = _re_system_boot_time.search(line)
        if match:
            split_line = re.split(r'\+|-', line.strip())
            return datetime.datetime.strptime(split_line[0], "%Y%m%d%H%M%S.%f")


def display_tasklist(ue_id=0):
    _send_ue_pc_cmd(ue_id=ue_id, cmd='tasklist')
    MolerTest.sleep(seconds=2)


@load_moler_configuration_from_tl()
def _send_ue_pc_cmd(ue_id, cmd):
    """
    Send any Windows command on UEPC(Send means that don't wait for the results).

    :param ue_id:   UE id - related to Test Line configuration - tl.ues.
    :param cmd:     Command to execute
    :return: None
    """
    ue_pc = DeviceFactory.get_device(name=ue_pc_name.format(ue_id))
    ue_pc.io_connection.moler_connection.sendline(data=cmd)


@load_moler_configuration_from_tl()
def _run_and_get_command_output(cmd, ue_id=0, timeout=30):
    """

    :param cmd:     Command to execute
    :param ue_id:   UE id - related to Test Line configuration - tl.ues.
    :param timeout: timeout for run command
    :return: full command results
    """
    ue_pc = DeviceFactory.get_device(name=ue_pc_name.format(ue_id))
    cmd_obj = ue_pc.get_cmd(cmd_name="cat",
                            cmd_params={'path': '/dev/null;{}'.format(cmd)})
    results = cmd_obj(timeout=timeout)
    return results['LINES']
